#![forbid(unsafe_code)]
use serde_json::{Value,json};
#[cfg(scope_p)]fn main(){use water_native_root::v1 as n;let index:Value=serde_json::from_str(&std::fs::read_to_string(std::env::var("WATER_SCOPE_FIXTURE_INDEX").unwrap()).unwrap()).unwrap();let id=water_contracts::v1::OpaqueId::new("scope-baseline").unwrap();let a=n::open_directory(&id,index["normal_a"].as_str().unwrap()).unwrap();let b=n::open_directory(&id,index["normal_b"].as_str().unwrap()).unwrap();let nested=n::open_directory(&id,index["nested"].as_str().unwrap()).unwrap();let alias=n::open_directory(&id,index["alias"].as_str().unwrap()).unwrap();assert_eq!(a.observation().identity(),alias.observation().identity());assert_ne!(a.observation().identity(),b.observation().identity());assert_ne!(a.observation().identity(),nested.observation().identity());assert_eq!(a.observation(),&a.refresh().unwrap());assert!(matches!(n::open_directory(&id,index["reparse"].as_str().unwrap()),Err(n::RootError::ReparsePoint)));assert!(!a.observation().authorization_granted()&&!a.observation().traversal_allowed());println!("{}",json!({"actual_N":true,"normal_roots":3,"alias_same_identity":true,"junction_rejected":true,"new_P_tested":false,"directory_enumerated":false}));}
#[cfg(scope_q)]fn main(){use water_contracts::v1 as a;let inputs:Value=serde_json::from_str(include_str!("../../contracts/redacted-report-v1/inputs.json")).unwrap();let mut cases=Vec::new();for c in inputs["cases"].as_array().unwrap(){let report=a::parse_report(&c["input"].to_string()).unwrap();let summary=water_summary_export::v1::summarize_report(&report).unwrap();cases.push(json!({"id":c["id"],"report":report,"summary":summary}));}let mut errors=Vec::new();for c in inputs["raw_errors"].as_array().unwrap(){let e=a::parse_report(c["input"].as_str().unwrap()).unwrap_err();let h=water_summary_export::v1::summarize_json(c["input"].as_str().unwrap()).unwrap_err();assert_eq!(e,h);errors.push(json!({"id":c["id"],"code":format!("{:?}",e.code),"field":e.field,"display":e.to_string()}));}println!("{}",json!({"cases":cases,"errors":errors,"actual_A_H":true,"new_Q_tested":false,"filesystem_scanned":false}));}
